<script>
import ResourceTabs from '@shell/components/form/ResourceTabs';
import Tab from '@shell/components/Tabbed/Tab';

export default {
  name: 'VeleroDeleteBackupRequestDetail',

  components: {
    ResourceTabs,
    Tab,
  },

  props: {
    value: {
      type:     Object,
      required: true,
    },
  },

  computed: {
    phase() {
      return this.value.status?.phase || 'Unknown';
    },

    phaseClass() {
      switch (this.phase) {
      case 'Processed':
        return 'status-success';
      case 'InProgress':
        return 'status-info';
      case 'Failed':
        return 'status-error';
      case 'New':
        return 'status-warning';
      default:
        return 'status-info';
      }
    },

    backupName() {
      return this.value.spec?.backupName || '-';
    },

    errors() {
      return this.value.status?.errors || [];
    },
  },
};
</script>

<template>
  <ResourceTabs
    :value="value"
    :mode="mode"
  >
    <Tab
      name="overview"
      label="Overview"
      :weight="100"
    >
      <div class="row mb-20">
        <div class="col span-12">
          <h3>Delete Backup Request Status</h3>
        </div>
      </div>

      <div class="detail-cards">
        <div class="detail-card">
          <h4>Status</h4>
          <span :class="['status-badge', phaseClass]">{{ phase }}</span>
        </div>

        <div class="detail-card">
          <h4>Backup Name</h4>
          <span>{{ backupName }}</span>
        </div>
      </div>

      <div v-if="errors.length > 0" class="row mb-20 mt-20">
        <div class="col span-12">
          <h3>Errors</h3>
          <div class="error-box">
            <ul>
              <li
                v-for="(error, index) in errors"
                :key="index"
              >
                {{ error }}
              </li>
            </ul>
          </div>
        </div>
      </div>
    </Tab>
  </ResourceTabs>
</template>

